import React from 'react';

import style from './style.module.less';
import PohAva from '../Ava';

interface IPohEmptyProps extends React.HTMLAttributes<HTMLDivElement> {
  image?: string;
  icon?: React.ReactElement<any>;
  height?: number;
}

const Empty: React.FC<IPohEmptyProps> = ({
  children,
  icon,
  height = 120,
  image = null,
  ...rest
}) => {
  return (
    <div
      className={style.empty}
      style={{ ...(rest.style || {}), minHeight: `${height}px` }}
      {...rest}
    >
      {image && <img src={image} alt="Empty" />}
      {icon && <PohAva icon={icon} width={86} />}
      {children || 'Пусто...'}
    </div>
  );
};

export default Empty;
